"""Replace 8 wrong brand logos with official assets."""
from __future__ import annotations

import re
import ssl
import urllib.request
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
LOGO_DIR = ROOT / "public" / "brands" / "logos"
BRANDS_TS = ROOT / "src" / "data" / "shop-brands.ts"

UA = {
    "User-Agent": (
        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
        "AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36"
    )
}
CTX = ssl.create_default_context()


def download(url: str, dest: Path) -> None:
    req = urllib.request.Request(url, headers=UA)
    with urllib.request.urlopen(req, context=CTX, timeout=60) as resp:
        data = resp.read()
    dest.write_bytes(data)
    print(f"OK  {dest.name}  ({len(data)} bytes)  <- {url[:90]}")


def darken_svg(text: str) -> str:
    text = re.sub(r'fill\s*=\s*"#fff(?:fff)?"', 'fill="#111111"', text, flags=re.I)
    text = re.sub(r"fill\s*=\s*'#fff(?:fff)?'", "fill='#111111'", text, flags=re.I)
    text = re.sub(r'fill\s*=\s*"white"', 'fill="#111111"', text, flags=re.I)
    text = re.sub(r"fill\s*=\s*'white'", "fill='#111111'", text, flags=re.I)
    text = re.sub(r"fill:\s*#fff(?:fff)?", "fill:#111111", text, flags=re.I)
    text = re.sub(r"fill:\s*white", "fill:#111111", text, flags=re.I)
    if 'fill="' not in text and "fill='" not in text and "fill:" not in text:
        text = text.replace("<svg", '<svg fill="#111111"', 1)
        text = re.sub(r"<path(?![^>]*fill=)", '<path fill="#111111"', text)
    return text


