def update_brands_ts() -> None:
    text = BRANDS_TS.read_text(encoding="utf-8")
    replacements = {
        'logo: "/brands/logos/essence.png"': 'logo: "/brands/logos/essence.svg"',
        'logo: "/brands/logos/purito-seoul.jpg"': 'logo: "/brands/logos/purito-seoul.svg"',
        'logo: "/brands/logos/seoul-1988.jpg"': 'logo: "/brands/logos/seoul-1988.png"',
        'logo: "/brands/logos/tocobo.png"': 'logo: "/brands/logos/tocobo.svg"',
        'logo: "/brands/logos/too-faced.png"': 'logo: "/brands/logos/too-faced.png"',
        'logo: "/brands/logos/skin1004.png"': 'logo: "/brands/logos/skin1004.png"',
        'logo: "/brands/logos/bourjois.svg"': 'logo: "/brands/logos/bourjois.svg"',
        'logo: "/brands/logos/la-girl.svg"': 'logo: "/brands/logos/la-girl.svg"',
    }
    for old, new in replacements.items():
        if old != new and old in text:
            text = text.replace(old, new)
            print(f"TS  updated path: {new}")
    BRANDS_TS.write_text(text, encoding="utf-8")


def main() -> None:
    LOGO_DIR.mkdir(parents=True, exist_ok=True)

    # Write inline official SVGs
    (LOGO_DIR / "essence.svg").write_text(ESSENCE_SVG, encoding="utf-8")
    print("OK  essence.svg  (official essence.eu wordmark)")
    (LOGO_DIR / "purito-seoul.svg").write_text(PURITO_SVG, encoding="utf-8")
    print("OK  purito-seoul.svg  (official purito.com wordmark)")
    (LOGO_DIR / "la-girl.svg").write_text(LA_GIRL_SVG, encoding="utf-8")
    print("OK  la-girl.svg  (official lagirlusa.com wordmark)")

    # Bourjois official Shopify SVG (often white) → darken for light cards
    bourjois_url = (
        "https://cdn.shopify.com/s/files/1/0248/4574/6285/files/bourjois_logo.svg?v=1634221351"
    )
    download(bourjois_url, LOGO_DIR / "bourjois.svg")
    svg = (LOGO_DIR / "bourjois.svg").read_text(encoding="utf-8", errors="ignore")
    (LOGO_DIR / "bourjois.svg").write_text(darken_svg(svg), encoding="utf-8")
    print("    darkened bourjois.svg fills for ivory cards")

    # Tocobo official
    download("https://tocobo.cafe24.com/wib/img/icon/logo.svg", LOGO_DIR / "tocobo.svg")
    svg = (LOGO_DIR / "tocobo.svg").read_text(encoding="utf-8", errors="ignore")
    (LOGO_DIR / "tocobo.svg").write_text(darken_svg(svg), encoding="utf-8")

    # SKIN1004 official store logo
    download(
        "https://www.skin1004.com/cdn/shop/files/SKIN1004_LOGO_300PX_30c77c72-0035-4b50-ba2c-f2c7a36a0d9d.png?v=1738771518&width=600",
        LOGO_DIR / "skin1004.png",
    )

    # Seoul 1988 is a K-SECRET line — use official K-SECRET logo
    download(
        "https://ksecretcosmetics.com/cdn/shop/files/KSECRET_LOGO1_210x@2x.png?v=1613593127",
        LOGO_DIR / "seoul-1988.png",
    )

    # Too Faced — official site logo asset (current homepage brand mark)
    download(
        "https://www.toofaced.com/media/export/cms/collection_pages/npl/2026/fall/peach/logo.png",
        LOGO_DIR / "too-faced.png",
    )

    # Remove obsolete wrong raster files where we switched to SVG/PNG
    for obsolete in (
        "essence.png",
        "purito-seoul.jpg",
        "seoul-1988.jpg",
        "tocobo.png",
    ):
        p = LOGO_DIR / obsolete
        if p.exists():
            p.unlink()
            print(f"DEL {obsolete}")

    update_brands_ts()
    print("Done.")


if __name__ == "__main__":
    main()
